Now I understand the structure. Let me implement the ticket_create tool in server.mjs.

Requirements:
- `ticket_create` tool with required non-empty `title` and `description`
- Optional `priority` enum low/normal/high (default normal)
- No extra fields (additionalProperties:false)
- Generate stable sequential ticket ids (t1, t2, ...)
- Return a concise text result
- Invalid arguments and unknown tools must reject

Let me write the server.mjs.

For the schema, I need:
- title: string, non-empty (minLength: 1)
- description: string, non-empty (minLength: 1)
- priority: enum [low, normal, high], default normal
- required: [title, description]
- additionalProperties: false

For callTool, need to:
- reject unknown tools
- validate arguments (the schema validation should handle it, but the protocol.mjs just calls callTool directly, so I need to do validation in server.mjs)

Let me look at how callTool is called in protocol.mjs: `callTool(req.params.name, req.params.arguments||{})`.

So callTool receives the name and arguments. I need to validate there. Since JSON schema validation isn't built into node, I'll do manual validation.

Let me write the implementation:

```js
let counter = 0;

export async function listTools() {
  return [{
    name: 'ticket_create',
    description: 'Create a support ticket',
    inputSchema: {
      type: 'object',
      properties: {
        title: { type: 'string', minLength: 1 },
        description: { type: 'string', minLength: 1 },
        priority: { type: 'string', enum: ['low', 'normal', 'high'], default: 'normal' }
      },
      required: ['title', 'description'],
      additionalProperties: false
    }
  }];
}

export async function callTool(name, args = {}) {
  if (name !== 'ticket_create') {
    throw new Error('Unknown tool: ' + name);
  }
  if (typeof args !== 'object' || args === null || Array.isArray(args)) {
    throw new Error('Invalid arguments');
  }
  const { title, description, priority = 'normal' } = args;
  if (typeof title !== 'string' || title.length === 0) {
    throw new Error('title is required and must be a non-empty string');
  }
  if (typeof description !== 'string' || description.length === 0) {
    throw new Error('description is required and must be a non-empty string');
  }
  if (!['low', 'normal', 'high'].includes(priority)) {
    throw new Error('priority must be one of low, normal, high');
  }
  // reject extra fields
  const allowed = ['title', 'description', 'priority'];
  for (const key of Object.keys(args)) {
    if (!allowed.includes(key)) {
      throw new Error('Unknown argument: ' + key);
    }
  }
  counter += 1;
  const id = 't' + counter;
  return {
    content: [{ type: 'text', text: `Ticket ${id} created: ${title} (${priority})` }]
  };
}
